        boolean rated = basis.rateInForce(person.gradeOn(today), today).isPresent();
        if (!rated && figures.isEmpty()) {
            return null;
        }
        BigDecimal sum = figures.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
        BigDecimal cap = basis.cap();
        return cap == null ? sum : sum.min(cap.subtract(cut).max(BigDecimal.ZERO.setScale(2)));
    }

    /** A holder's part of a claim's due figure: the figure times their share divided by 100,
     *  rounded half to even to two decimals. */
    public static BigDecimal part(BigDecimal figure, BigDecimal share) {
        return figure.multiply(share).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN);
    }

    /** The parts of a claim's due figure held by its share holders among those given (a share whose
     *  person is not among them, or is the claim's own person now, counts nowhere), by holder id in the order the shares were given;
     *  none when the figure is null. */
    public static Map<Long, BigDecimal> parts(Claim claim, BigDecimal figure, Set<Long> holders) {
        Map<Long, BigDecimal> parts = new LinkedHashMap<>();
        if (figure != null) {
            claim.getShares().stream()
                    .filter(s -> holders.contains(s.getPersonId()) && !s.getPersonId().equals(claim.getPersonId()))
                    .forEach(s -> parts.put(s.getPersonId(), part(figure, s.getShare())));
        }
        return parts;
    }

    /** What a claim's own person keeps of its due figure: the figure less the parts its holders
     *  among those given hold; null when the figure is. */
    public static BigDecimal kept(Claim claim, BigDecimal figure, Set<Long> holders) {
        if (figure == null) {
            return null;
        }
        return parts(claim, figure, holders).values().stream().reduce(figure, BigDecimal::subtract);
    }

    /** A claim's live due at the rate that applies to it (see {@link Basis#rateFor}): the one in
     *  force on the claim's date, for the person's grade in force on that date, that applies to it (taken from the sheet's ancestors when it has none
     *  of its own in force then): amount times pct divided by 100, rounded to two decimals by the claim's {@link #rounding} (the floor is
     *  applied later, see {@link #floored}); null when no rate applies on that date. */
    private BigDecimal due(Basis basis, Person person, Claim claim) {
        RoundingMode rounding = rounding(basis, claim);
        return basis.rateFor(person.gradeOn(claim.getDate()), claim)
                .map(Rate::getPct)
                .map(pct -> claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, rounding))
                .orElse(null);
    }

    /** How a claim's live figures round: by the sheet's rounding mode in force on the claim's date,
     *  or, when none is, half up when the date it rounds by (a correction's is that of the claim it
     *  corrects) is before the sheet's policy date, else half to even. */
    private RoundingMode rounding(Basis basis, Claim claim) {
        RoundingMode mode = basis.rounding(claim.getDate());
        if (mode != null) {
            return mode;
        }
        return claim.roundsBy().isBefore(basis.policyDateInForce()) ? RoundingMode.HALF_UP
                : RoundingMode.HALF_EVEN;
    }
}
package net.officefloor.hq.app.claim;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/** A share of a claim held by another person of its sheet: the person and their share percent (two
 *  decimals, above 0.00). The holder's due-total counts their part of the claim's due (see
 *  {@link Dues#part}), and the claim's own person's the rest. */
@Entity
@Table(name = "claim_share")
public class ClaimShare {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "share", nullable = false, precision = 5, scale = 2)
    private BigDecimal share;

    /** The sheet's today when the share was given; null when given before this was kept. */
    @Column(name = "on_day")
    private LocalDate on;

    protected ClaimShare() {
    }

    public ClaimShare(String sheetId, Long personId, BigDecimal share, LocalDate on) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.share = share;
        this.on = on;
    }

    public Long getId() {
        return id;
    }

    public Long getPersonId() {
        return personId;
    }

    public BigDecimal getShare() {
        return share;
    }

    public LocalDate getOn() {
        return on;
    }
}

